-- UBS Arena and Yankee Stadium maps (Sean, 2026-11-01: their seating charts, sent in chat). Drawn the way every other venue's is
-- (each level's sections clockwise by side, innermost level first). UBS Arena from the RateYourSeats end-stage chart (2024), drawn
-- for hockey, the stage end's 101 and 118 kept as the corners; the chart's 329 between 228 and 230 is read as 229. Yankee Stadium from
-- the Yankees' own chart, home plate at the bottom, the Bleachers (201 to 205, 235 to 239) on the 200 ring's outfield side; the field
-- MVP, Legends and Champions sections behind home (011 to 029) are left off, a ticket there starts from the nearest 100s section.
update public.ve_venues set layout = '{"field": "hockey", "ring_m": 500, "levels": [{"name": "100 level", "level": "100", "sides": {"top": ["102", "103", "104", "105", "106"], "tr": ["107"], "right": ["108", "109", "110"], "br": ["111"], "bottom": ["112", "113", "114", "115", "116", "117"], "bl": ["118"], "tl": ["101"]}}, {"name": "200 level", "level": "200", "sides": {"tl": ["201A", "201B", "202", "203"], "top": ["204", "205", "206", "207", "208"], "tr": ["209", "210", "211"], "right": ["212", "213", "214", "215"], "br": ["216", "217", "218"], "bottom": ["219", "220", "221", "222", "223"], "bl": ["224", "225", "226A", "226B"], "left": ["227", "228", "229", "230", "231"]}}, {"name": "300 level", "level": "300", "sides": {"tl": ["301", "302"], "top": ["303", "304", "305", "306", "307", "308"], "tr": ["309", "310", "311"], "right": ["312", "313", "314", "315"], "br": ["316", "317"], "bottom": ["318", "319", "320", "321", "322", "323"], "bl": ["324", "325", "326"]}}]}'::jsonb where slug = 'ubs-arena';
update public.ve_venues set layout = '{"field": "baseball", "ring_m": 900, "levels": [{"name": "Field level (100s)", "level": "100", "sides": {"tr": ["103", "104", "105", "106", "107", "108"], "right": ["109", "110", "111", "112", "113", "114A", "114B"], "br": ["115", "116", "117A", "117B"], "bottom": ["118", "119", "120", "121", "122"], "bl": ["123", "124", "125", "126"], "left": ["127", "128", "129", "130"], "tl": ["131", "132", "133", "134", "135", "136"]}}, {"name": "200 level (Main level and the Bleachers)", "level": "200", "sides": {"top": ["235", "236", "237", "238", "239", "201", "202", "203", "204", "205"], "right": ["206", "207", "208", "209", "210", "211", "212", "213", "214A", "214B"], "br": ["215", "216", "217", "218"], "bottom": ["219", "220", "221", "222", "223", "224"], "bl": ["225", "226", "227A", "227B"], "left": ["228", "229", "230", "231", "232A", "232B"], "tl": ["233A", "233B", "234"]}}, {"name": "300 level (Terrace)", "level": "300", "sides": {"right": ["305", "306", "307", "308", "309", "310", "311", "312", "313"], "br": ["314", "315", "316", "317", "318"], "bottom": ["319", "320A", "320B", "320C", "321", "322"], "bl": ["323", "324", "325", "326"], "left": ["327", "328", "329", "330", "331", "332A", "332B"], "tl": ["333", "334"]}}, {"name": "400 level (Grandstand)", "level": "400", "sides": {"right": ["405", "406", "407A", "407B", "408", "409", "410", "411", "412", "413"], "br": ["414", "415", "416", "417"], "bottom": ["418", "419", "420A", "420B", "420C", "421"], "bl": ["422", "423", "424", "425"], "left": ["426", "427", "428", "429", "430", "431A", "431B", "432A", "432B"], "tl": ["433", "434A", "434B"]}}]}'::jsonb where slug = 'yankee-stadium';

-- The two maps came from Sean, so they leave the map-the-venues research bounty (no one had claimed it); it keeps its 150 points for
-- the five airport gate maps still missing.
update public.ve_bounties set parts = array_remove(array_remove(parts, 'Yankee Stadium: the seating chart with every section number'),
    'UBS Arena: the seating chart with every section number (the Islanders layout)'),
  deliverable = 'Official maps (screenshot or PDF) with the link to each, for all five places', title = 'Find the official airport gate maps', updated_at = now()
where id = 'e6e9ee06-2dab-4331-8058-dc8f4400997b';
